package it.frociart.app;

import java.util.*;
import static it.frociart.app.FlowModel.*;

/** Emits JavaScript/TypeScript statements and structured control flow. No diagram interpreter is exported. */
final class FlowJavaScript {
    static String templateNumber(double value){return number(value);}
    private FlowJavaScript(){}
    static FlowSourceText generate(FlowSource.Program program,String runtime){return generate(program,runtime,false);}
    static FlowSourceText generate(FlowSource.Program program,String runtime,boolean typescript){if(runtime==null||runtime.trim().isEmpty())throw new IllegalArgumentException("Il supporto del linguaggio è vuoto.");return new Writer(program,typescript).generate(runtime);}
    static String literal(String text){if(text==null)return "null";StringBuilder b=new StringBuilder("\"");for(int i=0;i<text.length();i++){char c=text.charAt(i);if(c=='"')b.append("\\\"");else if(c=='\\')b.append("\\\\");else if(c=='\n')b.append("\\n");else if(c=='\r')b.append("\\r");else if(c=='\t')b.append("\\t");else if(c<32||c>126)b.append(String.format(Locale.ROOT,"\\u%04x",(int)c));else b.append(c);}return b.append('"').toString();}
    private static final Set<String> KEYWORDS=new HashSet<>(Arrays.asList("await break case catch class const continue debugger default delete do else enum export extends false finally for function if implements import in instanceof interface let new null package private protected public return static super switch this throw true try typeof var void while with yield as asserts any abstract async constructor declare from get infer is keyof module namespace never readonly require number object set string symbol type undefined unique unknown boolean bigint arguments eval __proto__ prototype toString valueOf hasOwnProperty isPrototypeOf propertyIsEnumerable __defineGetter__ __defineSetter__ __lookupGetter__ __lookupSetter__ then".split(" ")));
    private static String identifier(String name){StringBuilder b=new StringBuilder();for(char c:name.toCharArray())if(c>='a'&&c<='z'||c>='A'&&c<='Z'||c>='0'&&c<='9'||c=='_')b.append(c);else b.append(String.format(Locale.ROOT,"_u%04x",(int)c));String value=b.toString();if(value.isEmpty()||Character.isDigit(value.charAt(0)))value="value_"+value;if(value.startsWith("_fc")||KEYWORDS.contains(value))value="value_"+value;return value;}
    private static String unique(String seed,Set<String> names){String value=seed;int n=2;while(!names.add(value))value=seed+"_"+(n++);return value;}
    private static String number(double n){if(n==0)return "Value.number(0)";if(Math.abs(n)<=9000000000d){long power=1;for(int digits=0;digits<=6;digits++,power*=10){double scaled=n*power;if(scaled!=Math.floor(scaled))continue;String text=Long.toString((long)Math.abs(scaled));while(text.length()<digits+1)text="0"+text;if(digits>0)text=text.substring(0,text.length()-digits)+"."+text.substring(text.length()-digits);if(n<0)text="-"+text;if(Double.parseDouble(text)==n)return "Value.number("+text+")";}}return String.format(Locale.ROOT,"Value.number(numberFromBits(\"%016x\"))",Double.doubleToLongBits(n));}
    private static final class Symbol {final String name,original;Symbol(String name,String original){this.name=name;this.original=original;}}
    private static final class Helper {final String name;final FlowSource.Expression expression;final FlowSource.Block block;final Set<String> staged;final boolean track;Helper(String name,FlowSource.Expression e,FlowSource.Block b,Set<String> s,boolean t){this.name=name;expression=e;block=b;staged=new HashSet<>(s);track=t;}}
    private static final class Writer {
        final FlowSource.Program program;final FlowSourceText.Builder output;final boolean typed,references;
        final Map<String,String> functions=new HashMap<>(),classes=new HashMap<>();
        final Set<String> globals=new HashSet<>(Arrays.asList("Value","VectorValue","Variables","TypeSpec","ArrayCell","ArrayArgument","Runtime","Problem","Frame","TextFiles","Turtle","Number","String","Boolean","Object","Function","Array","Map","Set","Error","Math","BigInt","Date","JSON","RegExp","Promise","Symbol","WeakMap","TextDecoder","TextEncoder","DataView","Uint8Array","process","require","module","exports","globalThis","Infinity","NaN","undefined","_fc","run"));
        Map<String,Symbol> names;List<Symbol> symbols;Map<String,String> blockMethods;List<Helper> helpers;FlowSource.Scope scope;int temporary;
        Writer(FlowSource.Program p,boolean typescript){program=p;typed=typescript;boolean refs=false;for(FlowSource.Scope s:p.scopes)for(FlowSource.Parameter v:s.parameters)refs|=v.byReference;references=refs;output=new FlowSourceText.Builder(p,typed?"typescript":"javascript");int i=0;for(FlowSource.Scope s:p.scopes){classes.put(s.id,"_fc_Scope"+(i++));if(s.id!=null)functions.put(s.id,unique("flow_"+identifier(s.name),globals));}}
        String type(String value){return typed?": "+value:"";}
        void line(String text,int indent,FlowSource.Block block){output.addLine(text,indent,block==null?new FlowSourceText.Origin[0]:new FlowSourceText.Origin[]{new FlowSourceText.Origin(scope.id,block.id)});}
        void line(String text,int indent){line(text,indent,null);}
        FlowSourceText generate(String runtime){
            line("// Generato con Frociart — autore del software: mamt104",0);line("// Progetto: "+literal(program.title),0);
            line(typed?"// TypeScript per Node.js 22+. tsc --strict --target ES2020 --module node16 Programma.cts; node Programma.cjs.":"// JavaScript per Node.js 22+. Salva come Programma.cjs; esegui con node Programma.cjs.",0);line("\"use strict\";",0);line("let _fc"+type("Runtime")+";",0);
            for(FlowSource.Scope s:program.scopes){if(s.id!=null){List<String> args=new ArrayList<>(),values=new ArrayList<>();Set<String> used=new HashSet<>(globals);for(FlowSource.Parameter p:s.parameters){String n=unique(identifier(p.name),used);args.add(n+type("Value"));values.add(n);}boolean returns=s.returnType!=VOID;line("function "+functions.get(s.id)+"("+String.join(", ",args)+")"+type(returns?"Value":"Value | null")+" {",0);line("return "+(returns?"_fc.requireValue(":"")+"new "+classes.get(s.id)+"().run("+String.join(", ",values)+")"+(returns?")":"")+";",1);line("}",0);}writeScope(s);}
            line("",0);line("// --- Supporto dei tipi, dei limiti e delle operazioni di Frociart ---",0);for(String text:runtime.replace("\r\n","\n").replace('\r','\n').split("\n",-1))line(text,0);
            line("",0);line("if (require.main === module) {",0);line("_fc = new Runtime();",1);line("process.exitCode = _fc.run(() => new _fc_Scope0().run(), true) ? 0 : 1;",1);line("}",0);return output.build();
        }
        void collect(FlowSource.Expression e,java.util.function.Consumer<String> add){if(e==null)return;if(e.kind==FlowSource.ExpressionKind.Variable)add.accept(e.text);for(FlowSource.Expression child:e.children)collect(child,add);}
        void writeScope(FlowSource.Scope s){
            scope=s;temporary=0;names=new LinkedHashMap<>();symbols=new ArrayList<>();helpers=new ArrayList<>();blockMethods=new LinkedHashMap<>();Set<String> used=new HashSet<>(globals);
            java.util.function.Consumer<String> add=n->{if(n!=null&&!names.containsKey(n.toLowerCase(Locale.ROOT))){Symbol symbol=new Symbol(unique(identifier(n),used),n);names.put(n.toLowerCase(Locale.ROOT),symbol);symbols.add(symbol);}};
            for(FlowSource.Parameter p:s.parameters)add.accept(p.name);int index=0;for(FlowSource.Block b:s.blocks){blockMethods.put(b.id,"_fc_block"+(index++));FlowSource.Operation o=b.operation;if(o.input!=null){add.accept(o.input.name);collect(o.input.index,add);}if(o.declaration!=null){for(String n:o.declaration.names)add.accept(n);collect(o.declaration.size,add);}for(FlowSource.Write w:o.writes){add.accept(w.target.name);collect(w.value,add);collect(w.target.index,add);}collect(o.value,add);}
            line("",0);for(FlowSource.Block note:s.notes)line("// Annotazione: "+literal(note.text),0,note);for(FlowSource.Block b:s.blocks)if(b.comment!=null&&!b.comment.isEmpty())line("// Nota: "+literal(b.comment),0,b);
            line("class "+classes.get(s.id)+" {",0);for(Symbol sym:symbols){line(sym.name+type("Value | null")+" = null;",1);line("_fc_type_"+sym.name+type("TypeSpec | null")+" = null;",1);}
            List<String> args=new ArrayList<>(),pnames=new ArrayList<>(),pvalues=new ArrayList<>();index=0;for(FlowSource.Parameter p:s.parameters){String arg="_fc_arg"+(index++);args.add(arg+type("Value"));pnames.add(literal(p.name));pvalues.add(arg);}
            line("run("+String.join(", ",args)+")"+type("Value | null")+" {",1);line("_fc.guardCall();",2);index=0;for(FlowSource.Parameter p:s.parameters)line(member(p.name)+" = _fc."+(p.byReference?"checkReference":"checkType")+"(_fc_arg"+(index++)+", "+p.type+(p.byReference?"":", "+p.isArray)+");",2);
            line("_fc.enter("+literal(s.id==null?null:s.name)+", ["+String.join(", ",pnames)+"], ["+String.join(", ",pvalues)+"]"+(references?", true":"")+");",2);line("try {",2);line("_fc.checkMemory();",3);
            FlowSourcePlan plan=FlowSourcePlan.create(s);if(plan.structured)statements(plan.statements,3);else explicit(3);
            line("} catch (failure) {",2);line("_fc.captureError(); throw failure;",3);line("} finally { _fc.leave(); }",2);line("}",1);
            for(FlowSource.Block b:s.blocks)instruction(b);for(int i=0;i<helpers.size();i++){Helper h=helpers.get(i);line(h.name+"()"+type("Value")+" {",1,h.block);line("return "+expression(h.expression,h.block,h.staged,0,h.track)+";",2,h.block);line("}",1,h.block);}line("}",0);
        }
        String member(String n){return "this."+symbol(n).name;}
        Symbol symbol(String name){return names.get(name.toLowerCase(Locale.ROOT));}
        String name(String name,Set<String> staged){Symbol sym=symbol(name);return references?"_fc.lookup("+literal(sym.original)+")":"_fc.value("+(staged.contains(name.toLowerCase(Locale.ROOT))?"_fc.staged("+literal(sym.original)+")":"this."+sym.name)+", "+literal(sym.original)+")";}
        FlowSource.Scope callee(String id){if(id!=null)for(FlowSource.Scope s:program.scopes)if(id.equals(s.id))return s;return null;}
        boolean calls(FlowSource.Expression e){if(e==null)return false;if(e.functionId!=null)return true;for(FlowSource.Expression c:e.children)if(calls(c))return true;return false;}
        String expression(FlowSource.Expression e,FlowSource.Block block,Set<String> staged,int depth,boolean track){
            if(e==null)return "null";if(depth==0)track|=calls(e);if(depth>=24){String helper="_fc_expr"+(++temporary);helpers.add(new Helper(helper,e,block,staged,track));return "this."+helper+"()";}
            final boolean tracked=track;final int key=track?++temporary:0;
            java.util.function.Function<FlowSource.Expression,String> child=c->{String value=expression(c,block,staged,depth+1,tracked);return tracked?"_fc.hold("+key+", "+value+")":value;};
            java.util.function.Function<String,String> finish=value->tracked&&!e.children.isEmpty()?"_fc.release("+key+", "+value+")":value;
            switch(e.kind){
                case Number:return number(e.number);case Text:return "Value.text("+literal(e.text)+")";case Boolean:return "Value.logical("+e.bool+")";
                case Variable:return name(e.text,staged);
                case Vector:{List<String> values=new ArrayList<>();for(FlowSource.Expression c:e.children)values.add(child.apply(c));return finish.apply("Value.vector(["+String.join(", ",values)+"])");}
                case Index:{String target=child.apply(e.children.get(0));return finish.apply(references&&e.children.get(0).kind==FlowSource.ExpressionKind.Variable?"_fc.atName("+literal(symbol(e.children.get(0).text).original)+", () => "+child.apply(e.children.get(1))+")":"_fc.at("+target+", () => "+child.apply(e.children.get(1))+")");}
                case Unary:return finish.apply("_fc.unary("+literal(e.text)+", "+child.apply(e.children.get(0))+")");
                case Call:{FlowSource.Scope called=callee(e.functionId);List<String> values=new ArrayList<>();for(int i=0;i<e.children.size();i++){FlowSource.Expression c=e.children.get(i);values.add(called!=null&&called.parameters.get(i).byReference?"_fc.hold("+key+", _fc.reference("+literal(symbol(c.text).original)+", "+declaration(c.text)+", "+parameter(c.text)+"))":child.apply(c));}String args=String.join(", ",values);return e.functionId==null?finish.apply("_fc.intrinsic("+literal(e.text)+(args.isEmpty()?"":", "+args)+")"):"_fc.call("+key+", () => "+functions.get(e.functionId)+"("+args+"))";}
                case Binary:{String a=child.apply(e.children.get(0)),b=child.apply(e.children.get(1));if(e.text.equals("and")||e.text.equals("or"))return finish.apply("Value.logical("+a+".asBoolean() "+(e.text.equals("and")?"&&":"||")+" "+b+".asBoolean())");return finish.apply("_fc.binary("+literal(e.text)+", "+a+", "+b+")");}
                default:throw new IllegalArgumentException("Espressione non supportata nel sorgente.");
            }
        }
        String expression(FlowSource.Expression e,FlowSource.Block block){return expression(e,block,Collections.emptySet(),0,false);}
        void statements(List<FlowSourcePlan.Statement> list,int indent){for(FlowSourcePlan.Statement s:list){if(s.kind==FlowSourcePlan.Kind.Instruction){line((s.block.kind==END?"return ":"")+"this."+blockMethods.get(s.block.id)+"();",indent,s.block);}else if(s.kind==FlowSourcePlan.Kind.Repeat){line("do {",indent,s.entryBlock());statements(s.body,indent+1);line("} while ("+(s.loopOnTrue?"":"!")+"this."+blockMethods.get(s.block.id)+"().asBoolean());",indent,s.block);}else if(s.kind==FlowSourcePlan.Kind.While){line("while ("+(s.loopOnTrue?"":"!")+"this."+blockMethods.get(s.block.id)+"().asBoolean()) {",indent,s.block);statements(s.body,indent+1);line("}",indent,s.block);}else{line("if ("+"this."+blockMethods.get(s.block.id)+"().asBoolean()) {",indent,s.block);statements(s.body,indent+1);line("} else {",indent,s.block);statements(s.otherwise,indent+1);line("}",indent,s.block);}}}
        void explicit(int indent){line("// Collegamenti espliciti per conservare questo grafo.",indent);line("let _fc_next = "+literal(scope.startId)+";",indent);line("while (true) {",indent);line("switch (_fc_next) {",indent+1);for(FlowSource.Block b:scope.blocks){line("case "+literal(b.id)+":",indent+2,b);if(b.kind==DECISION)line("_fc_next = "+"this."+blockMethods.get(b.id)+"().asBoolean() ? "+literal(b.next("true"))+" : "+literal(b.next("false"))+"; break;",indent+3,b);else if(b.kind==END)line("return "+"this."+blockMethods.get(b.id)+"();",indent+3,b);else{line("this."+blockMethods.get(b.id)+"();",indent+3,b);line("_fc_next = "+literal(b.next("next"))+"; break;",indent+3,b);}}line("default: throw problem(\"Collegamento non valido nel sorgente modificato.\");",indent+2);line("}",indent+1);line("}",indent);}
        String declaration(String n){return "this._fc_type_"+symbol(n).name;}
        String parameter(String n){for(FlowSource.Parameter p:scope.parameters)if(p.name.equalsIgnoreCase(n))return "new TypeSpec("+p.type+", "+p.isArray+", 0)";return "null";}
        String convert(String value,String n){return "_fc.convert("+value+", "+declaration(n)+", "+parameter(n)+")";}
        void instruction(FlowSource.Block b){FlowSource.Operation o=b.operation;String method=blockMethods.get(b.id);line(method+"()"+type(b.kind==DECISION?"Value":"Value | null")+" {",1,b);java.util.function.Consumer<String> emit=text->line(text,2,b);
            if(b.kind==DECISION){emit.accept("return Value.logical(_fc.test(() => "+expression(o.value,b)+"));");line("}",1,b);return;}
            emit.accept(b.kind==INPUT?"_fc.guard();":"_fc.step();");
            if(b.kind==END){if(scope.id==null)emit.accept("_fc.finishFiles();");emit.accept(scope.id==null||scope.returnType==VOID?"return null;":"return _fc.checkType("+expression(o.value,b)+", "+scope.returnType+", "+scope.returnIsArray+");");line("}",1,b);return;}
            if(b.kind==PROCESS){emit.accept("_fc.begin();");Set<String> staged=new LinkedHashSet<>();List<FlowSource.Write> writes=o.writes;int start=temporary;
                List<String> assignmentNames=new ArrayList<>();for(int i=0;i<writes.size();i++){String part="_fc_assign"+(++temporary);assignmentNames.add(part);emit.accept("this."+part+"();");}
                emit.accept("_fc.commit();");for(FlowSource.Write w:writes)if(staged.add(w.target.name.toLowerCase(Locale.ROOT)))emit.accept(member(w.target.name)+" = _fc.variable("+literal(symbol(w.target.name).original)+");");emit.accept("return null;");line("}",1,b);staged.clear();
                for(int i=0;i<writes.size();i++){FlowSource.Write w=writes.get(i);line(assignmentNames.get(i)+"()"+type("void")+" {",1,b);String value=expression(w.value,b,staged,0,false);if(w.target.index!=null)value=references?"_fc.setAfterName("+value+", "+literal(symbol(w.target.name).original)+", () => "+expression(w.target.index,b,staged,0,false)+")":"_fc.setAfter("+value+", "+name(w.target.name,staged)+", () => "+expression(w.target.index,b,staged,0,false)+")";line("_fc.stage("+literal(symbol(w.target.name).original)+", "+convert(value,w.target.name)+(references&&w.target.index!=null?", true, true":"")+");",2,b);line("}",1,b);staged.add(w.target.name.toLowerCase(Locale.ROOT));}return;
            }
            if(b.kind==DECLARE){FlowSource.Declaration d=o.declaration;emit.accept("const _fc_size = integer("+(d.isArray()?expression(d.size,b):"Value.number(0)")+", 0, 1024, \"La dimensione\");");emit.accept("_fc.begin();");for(String n:d.names)emit.accept("_fc.stage("+literal(symbol(n).original)+", _fc.initial("+d.type+", "+d.isArray()+", _fc_size), false);");emit.accept("_fc.commit(true);");for(String n:d.names){emit.accept(member(n)+" = _fc.variable("+literal(symbol(n).original)+");");emit.accept(declaration(n)+" = new TypeSpec("+d.type+", "+d.isArray()+", _fc_size);");}}
            else if(b.kind==INPUT||b.kind==READ_FILE){FlowSource.Target t=o.input;String suffix=declaration(t.name)+", "+parameter(t.name)+", "+(t.index==null?"null, null":name(t.name,Collections.emptySet())+", () => "+expression(t.index,b));emit.accept(member(t.name)+" = _fc."+(b.kind==INPUT?"read(":"readFile(")+literal(symbol(t.name).original)+", "+(b.kind==INPUT?literal(b.prompt==null?"":b.prompt)+", ":"")+suffix+");");if(b.kind==INPUT)emit.accept("_fc.step();");}
            else if(b.kind!=START&&b.kind!=PAUSE){if(b.kind==OPEN_FILE)emit.accept("_fc.requireClosed("+o.fileReading+");");if(b.kind==WRITE_FILE)emit.accept("_fc.requireWrite();");String e=expression(o.value,b);switch(b.kind){case OUTPUT:emit.accept("_fc.emit("+e+(o.outputNewline?"":", false")+");");break;case CALL:emit.accept(e+";");break;case OPEN_FILE:emit.accept("_fc.openFile("+o.fileReading+", "+e+");");break;case WRITE_FILE:emit.accept("_fc.writeFile("+e+", "+o.fileNewline+");");break;case CLOSE_FILE:emit.accept("_fc.closeFile("+o.fileReading+");");break;case TURTLE_FORWARD:case TURTLE_TURN:case TURTLE_HOME:case TURTLE_CLEAR:case TURTLE_PEN:emit.accept("_fc.turtle("+b.kind+", "+e+", "+(b.kind==TURTLE_FORWARD?o.turtleDraw:o.turtleLeft)+");");break;default:throw new IllegalArgumentException("Blocco non supportato nel sorgente.");}}
            emit.accept("return null;");line("}",1,b);
        }
    }
}
